const post=async(u,q,v)=>{const r=await fetch(u,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query:q,variables:v})});return r.json()};
const A="https://api.v3.aave.com/graphql",M="https://api.morpho.org";
const RPC={1:"https://ethereum-rpc.publicnode.com",8453:"https://base-rpc.publicnode.com",42161:"https://arbitrum-one-rpc.publicnode.com",10:"https://optimism-rpc.publicnode.com"};
const rpc=async(c,method,params)=>{const r=await fetch(RPC[c],{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({jsonrpc:"2.0",id:1,method,params})});return (await r.json()).result};
const holder=async(c,tok)=>{const b=parseInt(await rpc(c,"eth_blockNumber",[]),16);const L=await rpc(c,"eth_getLogs",[{address:tok,fromBlock:"0x"+(b-3000).toString(16),toBlock:"latest",topics:["0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef"]}]);return (L||[]).map(l=>"0x"+l.topics[2].slice(26)).filter(a=>!/^0x0+$/.test(a)).slice(-1)[0]};
const g=async p=>{const r=await fetch(M+p,{headers:{accept:"application/json"}});return r.ok?r.json():{err:r.status}};
const intro=async t=>JSON.stringify((await post(A,`{__type(name:"${t}"){inputFields{name type{name kind ofType{name}}}}}`)).data);
console.log("AAVE WithdrawAmount",await intro("WithdrawAmount"));
const ah=await holder(8453,"0x4e65fE4DbA92790696d040ac24Aa414708F5c0AB");console.log("AAVE holder",ah);
const us=await post(A,`query($r:UserSuppliesRequest!){userSupplies(request:$r){market{address chain{chainId}} currency{symbol address decimals} balance{amount{value raw} usd} apy{value}}}`,{r:{markets:[{address:"0xA238Dd80C259a72e81d7e4664a9801593F98d1c5",chainId:8453},{address:"0x87870Bca3F3fD6335C3F4ce8392D69350B4fA4E2",chainId:1}],user:ah}});
console.log("AAVE USERSUP",JSON.stringify(us).slice(0,700));
const wq=await post(A,`query($r:WithdrawRequest!){withdraw(request:$r){__typename ...on TransactionRequest{to data value} ...on ApprovalRequired{reason approval{to data} originalTransaction{to data}} ...on InsufficientBalanceError{required{value}}}}`,{r:{market:"0xA238Dd80C259a72e81d7e4664a9801593F98d1c5",chainId:8453,sender:ah,amount:{erc20:{currency:"0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",value:{max:true}}}}});
console.log("AAVE WITHDRAW",JSON.stringify(wq).slice(0,900));
const mh=await holder(8453,"0xbeeF010f9cb27031ad51e3333f9aF9C6B1228183");console.log("MORPHO holder",mh);
console.log("MORPHO pos v1",JSON.stringify(await g("/v0/vaults-v1/users/"+mh+"/positions")).slice(0,900));
const m2h=await holder(8453,"0xbeef0e0834849aCC03f0089F01f4F1Eeb06873C9");console.log("MORPHO holder2",m2h);
console.log("MORPHO pos v2",JSON.stringify(await g("/v0/vaults-v2/users/"+m2h+"/positions")).slice(0,900));
console.log("MORPHO v2 detail",JSON.stringify(await g("/v0/vaults-v2/8453:0xbeef0e0834849aCC03f0089F01f4F1Eeb06873C9")).slice(0,1500));
console.log("MORPHO v2 state",JSON.stringify(await g("/v1/vaults-v2/8453:0xbeef0e0834849aCC03f0089F01f4F1Eeb06873C9/state")).slice(0,500));
console.log("MORPHO v2 apy",JSON.stringify(await g("/v1/vaults-v2/8453:0xbeef0e0834849aCC03f0089F01f4F1Eeb06873C9/apy-averages?lookback=seven_days")).slice(0,400));
const ASSET=/^(USDC|USDT|USD₮0|WETH|cbBTC|WBTC|EURC)$/;
const out=[];
for(const ver of ["v1","v2"]){const L=(await g(`/v0/vaults-${ver}?chain_ids=1,8453,42161,10&limit=1000`)).data||[];
 const C=L.filter(x=>/^(Steakhouse|Gauntlet|Spark|Moonwell|Smokehouse|Re7)/i.test(x.name));
 for(const x of C){const s=`${x.chain_id}:${x.vault_address}`;const d=(await g(`/v0/vaults-${ver}/${s}`)).data||{};const a=d.asset||{};if(!ASSET.test(a.symbol||""))continue;
  const st=(await g(`/${ver==="v1"?"v0":"v1"}/vaults-${ver}/${s}/state`)).data||{};const ap=(await g(`/${ver==="v1"?"v0":"v1"}/vaults-${ver}/${s}/apy-averages?lookback=seven_days`)).data||{};
  const fee=ver==="v1"?d.fee_wad:(d.performance_fee_wad||x.performance_fee_wad);const mf=x.management_fee_wad;
  out.push({ver,c:x.chain_id,a:x.vault_address,n:x.name,sym:a.symbol,dec:a.decimals,asset:a.address,tvl:Number(st.total_assets||0)/10**(a.decimals||18),apy:ap.apy,fee:fee?Number(fee)/1e16:0,mf:mf?Number(mf)/1e16:0})}}
const px={WETH:3000,cbBTC:90000,WBTC:90000};
out.sort((p,q)=>q.tvl*(px[q.sym]||1)-p.tvl*(px[p.sym]||1));
for(const o of out)console.log("MV",o.ver,o.c,o.a,o.n,"|",o.sym,o.dec,o.asset,"| tvl$",Math.round(o.tvl*(px[o.sym]||1)/1e6)+"M","apy",o.apy!=null?(o.apy*100).toFixed(2):"null","fee",o.fee.toFixed(1),"mf",o.mf);
